//! 🧯️ Failed real allocations retain the original edit donor and earlier backing.
use semio_framework_value_paged_list::{PagedList,PagedListEditCursor,PagedListEditFailure,PagedListEditOutcome,PagedListRefusalKind};
use semio_framework_value_control_contract::{RetainedCloneProgress,RetainedWorkPoll};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
fn receipt(p:semio_framework_value_paged_list::PagedListProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:usize::from(p.progressed),copied_bytes:p.placed_bytes,retained_capacity_bytes:p.allocated_bytes,released_bytes:p.released_allocation_bytes}}
#[test]fn edit_allocation_refusal_preserves_original_donor_and_partial_backing(){
 let law:serde_json::Value=serde_json::from_str(include_str!("faults.json")).unwrap();
 for row in law["cases"].as_array().unwrap(){let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut list=PagedList::<u64,16>::default();let mut item=Some(73u64);let mut cursor=PagedListEditCursor::insert(0,0);
  let grant=bank.loan(1,100000);let((poll,actual),heap)=observe(||bank.run(grant,4096,|effect|RetainedWorkPoll::Complete(cursor.step(&mut list,&mut item,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("binding must settle")};let PagedListEditOutcome::Ready(step)=turn.result.unwrap() else{panic!("funded binding denied")};assert_eq!(turn.work,1);assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));bank.post(receipt(step.progress),grant,heap);
  for _ in 0..row["successfulReservations"].as_u64().unwrap(){let grant=bank.loan(1,100000);let((poll,actual),heap)=observe(||bank.run(grant,4096,|effect|RetainedWorkPoll::Complete(cursor.step(&mut list,&mut item,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("reservation must settle")};let PagedListEditOutcome::Ready(step)=turn.result.unwrap() else{panic!("funded reservation denied")};assert!(step.progress.allocated_bytes>0);assert_eq!(actual,Some(step.progress.allocated_bytes));assert_eq!(bank.take_admitted(),Some(true));bank.post(receipt(step.progress),grant,heap);}
  let retained=list.allocated_bytes();if row["successfulReservations"].as_u64().unwrap()>0{assert!(retained>0)}let grant=bank.loan(1,100000);let(((poll,actual),attempts),heap)=observe(||refuse(||bank.run(grant,4096,|effect|RetainedWorkPoll::Complete(cursor.step(&mut list,&mut item,effect)))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("failed reservation must settle")};assert_eq!(attempts,row["attempts"].as_u64().unwrap()as usize);assert_eq!(turn.work,u128::from(row["work"].as_u64().unwrap()));assert_eq!(actual,Some(row["marker"].as_u64().unwrap()as usize));assert_eq!(heap,(0,0));assert_eq!(item,Some(73));assert_eq!(list.len(),0);assert_eq!(list.allocated_bytes(),retained);assert!(!cursor.is_finished());match turn.result.unwrap_err(){PagedListEditFailure::Allocation{error,copied_bytes}=>{assert_eq!(error.kind,PagedListRefusalKind::AllocationFailed);assert_eq!(error.allocated_bytes,row["allocated"].as_u64().unwrap()as usize);assert_eq!(copied_bytes,row["copied"].as_u64().unwrap()as usize);assert_eq!(error.work,row["work"].as_u64().unwrap())},other=>panic!("unexpected original refusal: {other:?}")};assert_eq!(bank.take_admitted(),Some(true));bank.post(Default::default(),grant,heap);
 }
}
